// The AI document studio's catalogue: the business documents people make,
// grouped the way they look for them. Each kind says what to ask (the AI asks
// more when the request needs it), the clauses a professional version must
// carry, and the Indian laws it's drafted against — so the draft and the
// review that follows hold it to that standard. Shared by the page (to show
// and ask) and the server (to draft and check).
import { z } from "zod";

export const CATEGORIES = [
  { id: "legal", name: "Legal & contracts", line: "Agreements, NDAs, MoUs and deeds", icon: "scale", tone: "#6366f1" },
  { id: "people", name: "HR & people", line: "Offer letters to exit letters and policies", icon: "users", tone: "#0ea5e9" },
  { id: "sales", name: "Sales & finance", line: "Quotes, proposals, POs, notices and plans", icon: "indian-rupee", tone: "#10b981" },
  { id: "corporate", name: "Corporate & compliance", line: "Resolutions, minutes and declarations", icon: "landmark", tone: "#f59e0b" },
  { id: "operations", name: "Operations & projects", line: "SOPs, RFPs, charters and reports", icon: "workflow", tone: "#8b5cf6" },
  { id: "letters", name: "Letters & notices", line: "Business letters, notices and memos", icon: "mail", tone: "#ec4899" },
  { id: "marketing", name: "Marketing & growth", line: "Plans, briefs, case studies and releases", icon: "megaphone", tone: "#f97316" },
] as const;
export type CategoryId = (typeof CATEGORIES)[number]["id"];

/** How a document is laid out: contracts open with parties and recitals; letters carry a letterhead. */
export const FORMS = ["contract", "letter", "policy", "report", "notice", "plan", "form"] as const;
export type Form = (typeof FORMS)[number];

export type QType = "text" | "long" | "date" | "money" | "number" | "select" | "email";
export type Question = { key: string; label: string; type: QType; options?: string[]; placeholder?: string; required?: boolean; help?: string };
export type DocKind = { id: string; name: string; category: CategoryId; line: string; form: Form; laws: string[]; clauses: string[]; questions: Question[]; keywords?: string; stamp?: boolean };

// ── Laws (cited where they apply) ───────────────────────────────────────────

