// ── Clauses (what an MNC-grade version carries) ─────────────────────────────

const C = {
  parties: "Parties and their particulars",
  recitals: "Recitals (background)",
  definitions: "Definitions and interpretation",
  scope: "Scope of work or services",
  deliverables: "Deliverables and acceptance",
  term: "Term and commencement",
  termination: "Termination (for convenience and for cause) and its consequences",
  fees: "Fees, invoicing and payment terms",
  taxes: "Taxes (GST, TDS) and withholding",
  confidentiality: "Confidentiality",
  ip: "Intellectual property ownership and licence",
  warranties: "Representations and warranties",
  indemnity: "Indemnity",
  liability: "Limitation of liability",
  forceMajeure: "Force majeure",
  data: "Data protection and privacy (DPDP Act)",
  nonSolicit: "Non-solicitation",
  nonCompete: "Restrictive covenants (enforceable under s.27 of the Contract Act)",
  insurance: "Insurance",
  audit: "Records and audit rights",
  compliance: "Compliance with laws, anti-bribery and anti-corruption",
  assignment: "Assignment and subcontracting",
  notices: "Notices",
  governingLaw: "Governing law and jurisdiction",
  disputes: "Dispute resolution (negotiation, then arbitration with seat and language)",
  entire: "Entire agreement",
  amendment: "Amendment and waiver",
  severability: "Severability",
  counterparts: "Counterparts and electronic signatures",
  survival: "Survival",
  relationship: "Independent contractors (no partnership or agency)",
  signatures: "Execution and signature blocks with witnesses",
  stampNote: "Stamp duty and registration note",
} as const;

/** The boilerplate every agreement carries. */
const BOILER = [C.notices, C.governingLaw, C.disputes, C.entire, C.amendment, C.severability, C.counterparts, C.assignment, C.forceMajeure, C.relationship, C.survival, C.signatures, C.stampNote];
const COMMERCIAL = [C.definitions, C.term, C.termination, C.fees, C.taxes, C.confidentiality, C.ip, C.warranties, C.indemnity, C.liability, C.data, C.compliance, ...BOILER];

// ── Questions (the AI asks more when the request needs it) ───────────────────

const q = (key: string, label: string, type: QType = "text", extra: Partial<Question> = {}): Question => ({ key, label, type, ...extra });
const PARTY = [q("party", "Other party's full legal name", "text", { required: true, placeholder: "Infosys Limited" }), q("partyType", "They are a", "select", { options: ["Company", "LLP", "Partnership firm", "Proprietorship", "Individual"] }), q("partyAddress", "Their registered address", "long")];
const DATES = [q("effectiveDate", "Effective date", "date"), q("term", "Term", "text", { placeholder: "2 years, auto-renewing yearly" })];
const MONEY = [q("amount", "Fees or value (₹)", "money"), q("paymentTerms", "Payment terms", "text", { placeholder: "Net 30 from invoice, by bank transfer" })];
const PERSON = [q("name", "Employee's full name", "text", { required: true }), q("designation", "Designation", "text", { required: true }), q("department", "Department")];
const SEAT = q("seat", "City for courts and arbitration", "text", { placeholder: "Mumbai" });

// ── The catalogue ───────────────────────────────────────────────────────────

const legal = (id: string, name: string, line: string, extra: Partial<DocKind> & { questions: Question[] }): DocKind => ({ id, name, category: "legal", line, form: "contract", laws: [L.contract, L.arbitration, L.stamp], clauses: COMMERCIAL, stamp: true, ...extra });
const people = (id: string, name: string, line: string, extra: Partial<DocKind> & { questions: Question[] }): DocKind => ({ id, name, category: "people", line, form: "letter", laws: [L.shops, L.wages, L.ss], clauses: [], ...extra });

